private val mu = Mutex()
private val flights = mutableMapOf<String, Deferred<Value>>()

suspend fun load(key: String): Value {
    val d = mu.withLock {
        flights[key] ?: appScope.async { source.read(key) }.also { f ->
            flights[key] = f
            f.invokeOnCompletion { appScope.launch { mu.withLock { flights.remove(key, f) } } }
        }
    }
    return d.await()                    // shared value or shared exception
}
